-- The two checklists published on 2026-10-29: Getting Back Into Reading
-- (Reading) and Taking Your Medication Every Day (Medication).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-29`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('getting-back-into-reading', 'Getting Back Into Reading', 'For wanting to read again when the phone keeps winning. It puts a book where the phone usually sits, counts five pages as reading, gives you permission to abandon one you are not enjoying, and lets the audiobook count.', 'Reading', '["Keep one book in the bag you always carry — the waiting room is where reading restarts.", "Count five pages as reading — the chapter is not the unit that matters.", "Put the book where the phone usually sits — the arm of the chair, the pillow, the table.", "Abandon the one you are not enjoying — finishing a bad book teaches you to avoid books.", "Read the first ten pages in the store — the opening tells you more than the reviews.", "Get a library card and borrow three — a due date does what a good intention cannot.", "Let the audiobook count — the commute and the dishes are reading time too.", "Tell one person what you are reading — a book talked about gets picked back up."]'::jsonb, 'weekly', array['Habits', 'Self-Care']::text[], 1, '2026-10-29T16:00:00+00:00'::timestamptz),
  ('taking-your-medication-every-day', 'Taking Your Medication Every Day', 'For a daily medication you keep forgetting or putting off. It ties the dose to something you already do, puts the refill a week ahead of the gap, keeps the side effects written down, and leaves stopping to a conversation with the prescriber.', 'Medication', '["Tie it to something you already do — teeth, coffee, feeding the dog.", "Use a box with the days on it — then the question is only whether the lid is up.", "Set the alarm for the same minute daily — a floating time is a missed dose waiting.", "Order the refill when a week is left — the gap at the end is where routines break.", "Keep one dose where you get caught out — a bag, a desk drawer, a coat pocket.", "Write side effects down with the date — the detail is gone by the next appointment.", "Ask the pharmacist about the awkward part — timing, food and the other bottles are their job.", "Never stop because you feel better — that is the conversation to have with the prescriber.", "Say so if the cost is the problem — there are cheaper versions and programs for this."]'::jsonb, 'daily', array['Habits', 'Body']::text[], 1, '2026-10-29T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
